describe('Modal Dialog Focus Management', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.get('#trigger-button').as('triggerButton'); // Replace with the actual selector for the trigger button
        cy.get('#modal').as('modal'); // Replace with the actual selector for the modal
    });

    it('should move focus back to the trigger button when the modal closes', () => {
        cy.get('@triggerButton').click();
        cy.get('@modal').should('be.visible');
        cy.get('@modal').find('.close-button').click(); // Replace with the actual selector for the close button
        cy.get('@triggerButton').should('be.focused');
    });

    it('should not lose focus on the trigger button if modal is closed without interaction', () => {
        cy.get('@triggerButton').click();
        cy.get('@modal').should('be.visible');
        cy.get('@modal').find('.overlay').click(); // Simulate clicking outside the modal to close it
        cy.get('@triggerButton').should('be.focused');
    });
});
